void fb_exit(void)
{
    uint32_t flags = kirq_save();

    if (!vga_graphics_mode) {
        kirq_restore(flags);
        return;
    }

    if (!fbcon_active) {
        vga_set_mode(mode3_misc, mode3_seq, sizeof(mode3_seq), mode3_crtc, sizeof(mode3_crtc),
                     mode3_gc, sizeof(mode3_gc), mode3_ac, sizeof(mode3_ac));

        vga_restore_text_palette();
        vga_restore_font();
    } else {
        fbcon_gfx_end();
    }

    vga_graphics_mode = false;

    gfx_current.mode = GFX_MODE_NONE;
    gfx_current.width = 0;
    gfx_current.height = 0;
    gfx_current.bpp = 0;
    gfx_current.pitch = 0;
    gfx_current.framebuffer = NULL;
    gfx_current.size = 0;

    k_cls();
    kirq_restore(flags);
}

