void textcon_release(void)
{
    uint32_t flags = kirq_save();

    if (_hold > 0) {
        _hold--;
    }
    if (_hold == 0 && _cursor_stale) {
        vga_text_update_cursor();
    }
    kirq_restore(flags);
}

